#include <oauth/GoogleDriveBackupClient.hpp>
#include <QCoreApplication>
#include <QThread>
#include <QElapsedTimer>
#include "facts.hpp"
#include <iostream>
#include <thread>
#include <functional>
using namespace std;
int checks=0,failures=0;
void Check(bool ok,const char*n){++checks;if(!ok){++failures;cerr<<"FAIL "<<n<<'\n';}}
using Session=GoogleDriveBackupClient::SessionInfo;
OAuthClientRegistration registration;
Session Original(){Session result;QString error;bool connected=false;thread worker([&]{connected=GoogleDriveBackupClient::HasConnection(error,{},&result);});worker.join();Check(connected&&error.isEmpty(),"original credential session observed before request");return result;}
void Replace(){OAuthTokenSet token;token.accessToken="qa-cloud-B";token.refreshToken="qa-next-refresh";token.expiresAt=4102444800;QString error;bool ok=false;thread worker([&]{ok=GoogleDriveBackupClient::StoreTokens(token,error);});worker.join();Check(ok,"new session really stored before comparison");}
template<class F>bool Spin(F ready,int limit=3000){QElapsedTimer t;t.start();while(!ready()&&t.elapsed()<limit)QThread::msleep(1);return ready();}
using Request=function<bool(QString&,const Session&)>;
Request Operation(int kind){return[kind](QString&e,const Session&s){vector<GoogleDriveBackupItem>items;GoogleDriveBackupItem item;QByteArray archive;QString name;switch(kind){case 0:return GoogleDriveBackupClient::List(items,e,registration,{},s);case 1:return GoogleDriveBackupClient::Upload("qa-archive","qa","qa",QDateTime::currentDateTimeUtc(),false,item,e,registration,{},s);case 2:return GoogleDriveBackupClient::Download("qa-item-A",archive,e,registration,{},s);case 3:return GoogleDriveBackupClient::Remove("qa-item-A",e,registration,{},s);case 4:return GoogleDriveBackupClient::Prune(1,e,registration,{},s);case 5:return GoogleDriveBackupClient::AccountName(name,e,registration,{},s);default:return GoogleDriveBackupClient::ValidateSession(s,e);}};}
void StalePreflight(){for(int kind=0;kind<7;++kind){ResetFacts();SeedCloud();const auto old=Original();Replace();QString error;bool accepted=true;thread worker([&]{accepted=Operation(kind)(error,old);});worker.join();Check(!accepted&&!error.isEmpty(),"stale expected session rejected before request");Check(httpCalls==0,"stale expected session sends no HTTP for any remote operation");}}
void ChangedInFlight(int kind,bool secondUploadPhase=false){ResetFacts();SeedCloud();const auto old=Original();httpDelay=100;QString error;bool accepted=true;thread worker([&]{accepted=Operation(kind)(error,old);});Check(Spin([&]{return httpActive>0&&(!secondUploadPhase||httpCalls>=1);}),"real fake transport phase entered before credential replacement");Replace();worker.join();Check(!accepted&&!error.isEmpty(),"in-flight old session response is not accepted locally after replacement");if(kind==1)Check(httpCalls==(secondUploadPhase?2:1),"multipart never advances to next phase after session mismatch");}
void PruneExternalBoundary(bool explicitExpected){ResetFacts();SeedCloud();const auto old=Original();loads=0;richListResponses=true;richListExtra=true;SetCloudReplacementAtLoad(explicitExpected?2:3,R"({"access_token":"qa-external-B"})");QString error;bool accepted=true;thread worker([&]{accepted=GoogleDriveBackupClient::Prune(1,error,registration,{},explicitExpected?optional<Session>(old):nullopt);});worker.join();Check(externalLoadReplacements==1,"external RAW replacement injected exactly at prune removal token load");Check(!accepted&&!error.isEmpty()&&httpCalls==1,"Prune binds list/removals to one session and never deletes item A with token B");}
void AuthorizedBearer(){ResetFacts();SeedCloud();Original();OAuthTokenSet issued;issued.accessToken="qa-explicit-issued";QString name,error;bool ok=false;int before=loads;thread worker([&]{ok=GoogleDriveBackupClient::AuthorizedAccountName(issued,name,error);});worker.join();Check(ok&&!name.isEmpty()&&loads==before&&httpCalls==1,"authorized account lookup uses supplied bearer without recapturing namespace mutex/token");}
void Pagination(bool replace){ResetFacts();SeedCloud();auto old=Original();richListResponses=true;nextPageOnce=true;if(replace)httpDelay=100;QString error;bool ok=false;vector<GoogleDriveBackupItem>items;thread worker([&]{ok=GoogleDriveBackupClient::List(items,error,registration,{},old);});if(replace){Check(Spin([]{return httpActive>0;}),"first page transport reached before session replacement");Replace();}worker.join();if(replace)Check(!ok&&!error.isEmpty()&&httpCalls==1&&items.empty(),"replaced session stops before second page and never accepts old partial history");else Check(ok&&httpCalls==2&&items.size()==2&&items[0].id!=items[1].id,"stable session paginates two schema-valid distinct items using same bearer");}
int main(int argc,char**argv){QCoreApplication app(argc,argv);registration.clientId="qa-client";StalePreflight();ChangedInFlight(0);ChangedInFlight(1);ChangedInFlight(1,true);ChangedInFlight(2);ChangedInFlight(3);PruneExternalBoundary(true);PruneExternalBoundary(false);Pagination(false);Pagination(true);AuthorizedBearer();Check(ioOnGui==0&&configOnWorker==0,"session tests retain worker-only credential IO and no worker config");cout<<"{\"checks\":"<<checks<<",\"failures\":"<<failures<<",\"passed\":"<<(failures?"false":"true")<<"}\n";return failures?1:0;}
